data.vllm_pod_diagnostics.py:
"""Report vLLM deployment readiness, pod failures, and warnings on Azure K3s."""

import json
import subprocess


NAMESPACE = "vllm-example"
DEPLOYMENT = "vllm-gemma-deployment"


def controller_uid(resource):
    owners = resource["metadata"].get("ownerReferences", [])
    return next((owner["uid"] for owner in owners if owner.get("controller")), None)


def pod_is_ready(status):
    return any(
        condition["type"] == "Ready" and condition["status"] == "True"
        for condition in status.get("conditions", [])
    )


def explain_failure(reason, message):
    if reason == "Evicted" and "ephemeral-storage" in message:
        return "The node ran low on local storage. Check free disk space and the node's DiskPressure condition."
    if reason == "UnexpectedAdmissionError" and "no healthy devices" in message and "nvidia.com/gpu" in message:
        return "Kubernetes had no healthy GPU to assign at admission. Check the NVIDIA device plugin and node GPU status."
    return "Inspect the pod's message and recent Kubernetes events."


def pod_warning_lines(items):
    pods_by_uid = {item["metadata"]["uid"]: item for item in items if item["kind"] == "Pod"}
    warnings = [item for item in items if item["kind"] == "Event" and item.get("type") == "Warning"]
    warnings.sort(key=lambda event: event["metadata"].get("creationTimestamp", ""), reverse=True)

    lines = []
    for event in warnings:
        subject = event.get("involvedObject") or event.get("regarding", {})
        if subject.get("kind") != "Pod":
            continue

        reason = event.get("reason", "Unspecified")
        message = (event.get("message") or event.get("note") or "").strip()
        last_seen = (
            (event.get("series") or {}).get("lastObservedTime")
            or event.get("lastTimestamp")
            or event.get("deprecatedLastTimestamp")
            or event.get("eventTime")
            or event["metadata"].get("creationTimestamp", "Unknown")
        )
        lines.append(f"  {subject.get('name', 'Unknown pod')} | {reason} | Last seen {last_seen}")
        if message:
            lines.append(f"    {message}")

        pod = pods_by_uid.get(subject.get("uid"))
        if pod is not None:
            status = pod.get("status", {})
            phase = "Terminating" if pod["metadata"].get("deletionTimestamp") else status.get("phase", "Unknown")
            lines.append(f"    Current pod {phase} | Ready={pod_is_ready(status)}")

        if reason == "Unhealthy" and message.startswith("Readiness probe failed") and "deadline exceeded" in message:
            lines.append("    The readiness probe timed out. Check recent pod logs if the timeout recurs.")
    return lines


def summarize(items):
    deployment = next(
        (item for item in items if item["kind"] == "Deployment" and item["metadata"]["name"] == DEPLOYMENT),
        None,
    )
    if deployment is None:
        raise ValueError(f"Deployment {DEPLOYMENT} is missing from namespace {NAMESPACE}.")

    metadata = deployment["metadata"]
    status = deployment.get("status", {})
    desired = deployment["spec"].get("replicas", 1)
    ready = status.get("readyReplicas", 0)
    available = status.get("availableReplicas", 0)

    if status.get("observedGeneration", 0) < metadata.get("generation", 0):
        availability = "RECONCILING"
    elif desired == 0:
        availability = "SCALED TO ZERO"
    elif available >= desired:
        availability = "AVAILABLE"
    else:
        availability = "WAITING FOR REPLICAS"

    replica_set_uids = {
        item["metadata"]["uid"]
        for item in items
        if item["kind"] == "ReplicaSet" and controller_uid(item) == metadata["uid"]
    }
    pods = [item for item in items if item["kind"] == "Pod" and controller_uid(item) in replica_set_uids]

    current = []
    failures = []
    for pod in sorted(pods, key=lambda item: item["metadata"]["name"]):
        name = pod["metadata"]["name"]
        pod_status = pod.get("status", {})
        phase = pod_status.get("phase", "Unknown")
        if phase == "Failed":
            reason = pod_status.get("reason", "Unspecified")
            message = pod_status.get("message", "")
            failures.append(f"  {name} | {reason}")
            if message:
                failures.append(f"    {message.strip()}")
            failures.append(f"    {explain_failure(reason, message)}")
        elif phase != "Succeeded":
            pod_ready = pod_is_ready(pod_status)
            restarts = sum(container["restartCount"] for container in pod_status.get("containerStatuses", []))
            if pod["metadata"].get("deletionTimestamp"):
                phase = "Terminating"
            current.append(f"  {name} | {phase} | Ready={pod_ready} | Restarts={restarts}")

    lines = [f"{DEPLOYMENT} | {availability} | Ready {ready}/{desired} | Available {available}/{desired}"]
    if current:
        lines.extend(["", "Current pods", *current])
    if failures:
        lines.extend(["", "Failed pod records", *failures])
    warnings = pod_warning_lines(items)
    lines.extend(["", "Recent pod warnings", *(warnings or ["  0 pod warning events in this namespace."])])
    return "\n".join(lines)


def main():
    command = ["sudo", "k3s", "kubectl", "-n", NAMESPACE, "get", "deployments,replicasets,pods,events", "-o", "json"]
    try:
        snapshot = json.loads(subprocess.check_output(command, text=True, timeout=30))
        print(summarize(snapshot["items"]))
    except (OSError, ValueError, subprocess.SubprocessError) as error:
        raise SystemExit(f"Could not generate the vLLM report. {error}") from None


if __name__ == "__main__":
    main()
